package dev.veltraph.client.combat.ghost;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import dev.veltraph.client.combat.ghost.GhostSourceSampledRay.Point;
class GhostLootPickupTransactionTest {
    private static GhostSourceOwnedParentArea.Stamp scope(){return new GhostSourceOwnedParentArea.Stamp(new Object(),1,2,new Object(),new Object(),new Object());}
    private static GhostLootCandidatePlanner.Candidate item(int count){return new GhostLootCandidatePlanner.Candidate(new Object(),17,UUID.randomUUID(),"SORROW","ALL-components-v1",count,new Point(3,75,4),true);}
    private static GhostLootPickupTransaction.Pickup packet(GhostLootCandidatePlanner.Candidate item,long serial,int amount){return new GhostLootPickupTransaction.Pickup(serial,item.entityId(),item.uuid(),item.unitIdentity(),amount);}
    @Test void InventoryIncreaseWithoutMatchingNativePickupCannotCredit(){var s=scope();var t=new GhostLootPickupTransaction(s,item(2),8,10,0,1000);assertEquals(GhostLootPickupTransaction.State.WAITING,t.observeInventory(s,10,100));assertEquals(0,t.creditedUnits());}
    @Test void PacketOrDisappearanceWithoutInventoryIncreaseCannotCredit(){var s=scope();var i=item(2);var t=new GhostLootPickupTransaction(s,i,8,10,0,1000);assertTrue(t.observeActualLocalPickup(s,packet(i,11,2)));assertEquals(GhostLootPickupTransaction.State.WAITING,t.observeInventory(s,8,100));assertEquals(0,t.creditedUnits());}
    @Test void ActualPartialAndCompleteDeliveryUsesBothWitnesses(){var s=scope();var i=item(3);var t=new GhostLootPickupTransaction(s,i,8,10,0,1000);assertTrue(t.observeActualLocalPickup(s,packet(i,11,1)));assertEquals(GhostLootPickupTransaction.State.PARTIAL,t.observeInventory(s,9,100));assertEquals(1,t.creditedUnits());assertTrue(t.observeActualLocalPickup(s,packet(i,12,2)));assertEquals(GhostLootPickupTransaction.State.COMPLETE,t.observeInventory(s,11,200));assertEquals(3,t.creditedUnits());}
    @Test void PacketReplayAndForeignItemOrFullComponentIdentityCannotCredit(){var s=scope();var i=item(2);var t=new GhostLootPickupTransaction(s,i,0,10,0,1000);assertFalse(t.observeActualLocalPickup(s,packet(i,10,2)));assertFalse(t.observeActualLocalPickup(s,new GhostLootPickupTransaction.Pickup(11,i.entityId(),i.uuid(),"other-components",2)));assertFalse(t.observeActualLocalPickup(s,new GhostLootPickupTransaction.Pickup(12,i.entityId(),UUID.randomUUID(),i.unitIdentity(),2)));assertFalse(t.observeActualLocalPickup(s,new GhostLootPickupTransaction.Pickup(13,18,i.uuid(),i.unitIdentity(),2)));assertEquals(0,t.creditedUnits());assertEquals(GhostLootPickupTransaction.State.WAITING,t.observeInventory(s,2,100));}
    @Test void GenerationSettingsPwcDriftRevokesBeforeReceiptOrInventory(){var s=scope();var i=item(2);var changed=new GhostSourceOwnedParentArea.Stamp(s.parent(),s.generation()+1,s.settingsRevision(),s.player(),s.world(),s.connection());var t=new GhostLootPickupTransaction(s,i,0,10,0,1000);assertFalse(t.observeActualLocalPickup(changed,packet(i,11,2)));assertEquals(GhostLootPickupTransaction.State.REVOKED,t.observeInventory(s,2,100));assertEquals(0,t.creditedUnits());var t2=new GhostLootPickupTransaction(s,i,0,10,0,1000);assertTrue(t2.observeActualLocalPickup(s,packet(i,11,2)));assertEquals(GhostLootPickupTransaction.State.REVOKED,t2.observeInventory(scope(),2,100));assertEquals(0,t2.creditedUnits());}
    @Test void NativeInventoryDecreaseDoesNotFabricateNegativeOrFutureCredit(){var s=scope();var i=item(2);var t=new GhostLootPickupTransaction(s,i,8,10,0,1000);t.observeActualLocalPickup(s,packet(i,11,2));assertEquals(GhostLootPickupTransaction.State.WAITING,t.observeInventory(s,6,100));assertEquals(0,t.creditedUnits());assertEquals(GhostLootPickupTransaction.State.PARTIAL,t.observeInventory(s,9,200));assertEquals(1,t.creditedUnits());}
    @Test void TimeoutAndExplicitRevokeLeaveUnprovenUnitsUncredited(){var s=scope();var i=item(2);var t=new GhostLootPickupTransaction(s,i,0,10,0,1000);assertEquals(GhostLootPickupTransaction.State.WAITING,t.observeInventory(s,0,999));assertEquals(GhostLootPickupTransaction.State.TIMED_OUT,t.observeInventory(s,0,1000));assertFalse(t.observeActualLocalPickup(s,packet(i,11,2)));assertEquals(GhostLootPickupTransaction.State.TIMED_OUT,t.observeInventory(s,2,1001));assertEquals(0,t.creditedUnits());var other=new GhostLootPickupTransaction(s,i,0,10,0,1000);other.revoke();assertFalse(other.observeActualLocalPickup(s,packet(i,11,2)));assertEquals(0,other.creditedUnits());}
    @Test void AmountAndInventoryAreCappedToActualChosenStackCount(){var s=scope();var i=item(2);var t=new GhostLootPickupTransaction(s,i,0,10,0,1000);assertTrue(t.observeActualLocalPickup(s,packet(i,11,Integer.MAX_VALUE)));assertEquals(GhostLootPickupTransaction.State.COMPLETE,t.observeInventory(s,Integer.MAX_VALUE,100));assertEquals(2,t.creditedUnits());assertFalse(t.observeActualLocalPickup(s,packet(i,12,1)));assertEquals(2,t.creditedUnits());}
}
